  v.innerHTML='<div class="crumb"><button data-go="home">Course</button> / <button data-go="'+m.id+'">Module '+m.idx+'</button> / Lesson '+l.n+'</div><div class="eyebrow">Module '+m.idx+' &middot; Lesson '+l.n+' &middot; '+l.m+' min</div><h1 style="font-size:clamp(1.7rem,3.6vw,2.4rem)">'+esc(l.t)+'</h1><div class="lesson">'+l.h+'</div>'+
  '<div class="nav"><div>'+(prev?'<button class="btn ghost" data-go="'+prev.id+'">&larr; Previous</button>':'')+'</div><div class="row"><button class="btn" id="done">'+(store.done[l.id]?'Completed. Continue':'Mark complete and continue')+' &rarr;</button></div></div>'+disclaimer();
  $('#done').onclick=function(){store.done[l.id]=1;save();go(last?m.id+'-quiz':(next?next.id:'final'))};
