function quiz(v,m){
  var qs=m.quiz;runQuiz(v,qs,{title:'Module '+m.idx+' quiz',crumb:'<button data-go="home">Course</button> / <button data-go="'+m.id+'">Module '+m.idx+'</button> / Quiz',onFinish:function(s){if(store.quiz[m.id]==null||s>store.quiz[m.id]){store.quiz[m.id]=s;save()}},after:'<button class="btn" data-go="'+m.id+'-work">Go to the assignment &rarr;</button>'});
}
function runQuiz(v,qs,o){
  var ans=[],score=0,cur=0;
  function draw(){
    var h='<div class="crumb">'+o.crumb+'</div><div class="eyebrow">Knowledge check</div><h1 style="font-size:clamp(1.7rem,3.6vw,2.4rem)">'+esc(o.title)+'</h1>';
    if(cur>=qs.length){
      var pct=Math.round(100*score/qs.length);
      h+='<div class="callout '+(pct>=80?'':'warn')+'"><strong class="t">Result</strong><p style="font-size:1.3rem;margin:0"><b>'+score+' of '+qs.length+'</b> ('+pct+'%). '+(pct>=80?'Solid. Move on.':'Review the lessons where you missed questions, then retake it.')+'</p></div><div class="row"><button class="btn ghost" id="again">Retake</button>'+(o.after||'')+'</div>';
      v.innerHTML=h;$('#again').onclick=function(){ans=[];score=0;cur=0;draw()};$$('[data-go]',v).forEach(function(b){b.onclick=function(){go(b.getAttribute('data-go'))}});
      if(o.onFinish)o.onFinish(score);return;
    }
    for(var i=0;i<=cur;i++){
      var q=qs[i];
      h+='<div class="q"><div class="qn">Question '+(i+1)+' of '+qs.length+'</div><div class="qt">'+q.q+'</div>';
      q.o.forEach(function(op,j){
        var cls='',dis='';
        if(ans[i]!=null){dis=' disabled';if(j===q.a)cls=' right';else if(j===ans[i])cls=' wrong'}
        h+='<button class="opt'+cls+'" data-q="'+i+'" data-o="'+j+'"'+dis+'>'+op+'</button>';
      });
      if(ans[i]!=null)h+='<div class="why"><b>'+(ans[i]===q.a?'Correct. ':'Not quite. ')+'</b>'+q.e+'</div>';
      h+='</div>';
    }
    if(ans[cur]!=null)h+='<button class="btn" id="nx">'+(cur===qs.length-1?'See result':'Next question')+'</button>';
    v.innerHTML=h;
    $$('.opt',v).forEach(function(b){b.onclick=function(){var qi=+b.getAttribute('data-q'),oi=+b.getAttribute('data-o');if(ans[qi]!=null)return;ans[qi]=oi;if(oi===qs[qi].a)score++;draw()}});
    var nx=$('#nx');if(nx)nx.onclick=function(){cur++;draw();window.scrollTo(0,0)};
    $$('[data-go]',v).forEach(function(b){b.onclick=function(){go(b.getAttribute('data-go'))}});
  }
  draw();
}
