/* ---------- widgets ---------- */
function fld(id,label,val,step,min){return '<label class="f">'+label+'<input type="number" id="'+id+'" value="'+val+'" step="'+(step||'any')+'"'+(min!=null?' min="'+min+'"':'')+'></label>'}
function g(root,id){return parseFloat($('#'+id,root).value)}
function outs(list){return '<div class="out">'+list.map(function(o){return '<div>'+o[0]+'<b id="'+o[1]+'">-</b></div>'}).join('')+'</div>'}
function setT(root,id,t,cls){var e=$('#'+id,root);if(e){e.textContent=t;e.className=cls||''}}
var uid=0;
var W={};
W.possize=function(el){
  var u='p'+(++uid);
  el.innerHTML='<div class="tool"><h4>Position size calculator</h4><div class="sub">Shares = (account x risk %) / (entry - stop). The stop distance sets the size, not your buying power.</div><div class="fields">'+fld(u+'a','Account ($)',10000,100)+fld(u+'r','Risk per trade (%)',1,0.1)+fld(u+'e','Entry price',48.55,0.01)+fld(u+'s','Stop price',48.05,0.01)+fld(u+'t','Target price',49.55,0.01)+'</div>'+outs([['Dollars at risk (1R)',u+'1'],['Shares',u+'2'],['Position value',u+'3'],['Reward-to-risk',u+'4'],['% of account in trade',u+'5']])+'<div class="note" id="'+u+'n"></div></div>';
  function c(){var A=g(el,u+'a'),R=g(el,u+'r'),E=g(el,u+'e'),S=g(el,u+'s'),T=g(el,u+'t');var risk=A*R/100,dist=Math.abs(E-S),sh=dist>0?Math.floor(risk/dist):0;
    setT(el,u+'1',money(risk));setT(el,u+'2',num(sh,0));setT(el,u+'3',money(sh*E));setT(el,u+'4',dist>0?num(Math.abs(T-E)/dist,2)+' : 1':'-');setT(el,u+'5',num(100*sh*E/A,0)+'%');
    var n=[];if(R>2)n.push('Risking more than 2% per trade is aggressive for a beginner.');if(sh*E>A)n.push('This position is larger than your account, so it needs margin or leverage.');if(E>S&&T<E)n.push('For a long trade the target should be above entry.');
    $('#'+u+'n',el).textContent=n.join(' ')}
  $$('input',el).forEach(function(i){i.oninput=c});c();
};
W.expect=function(el){
  var u='x'+(++uid);
  el.innerHTML='<div class="tool"><h4>Expectancy calculator</h4><div class="sub">Expectancy = (win rate x average win) - (loss rate x average loss) - costs. Positive means an edge on paper.</div><div class="fields">'+fld(u+'w','Win rate (%)',40,1)+fld(u+'aw','Average win ($)',200,1)+fld(u+'al','Average loss ($)',100,1)+fld(u+'c','Cost per trade ($)',6,1)+'</div>'+outs([['Expectancy per trade',u+'1'],['In R multiples',u+'2'],['Profit factor',u+'3'],['Break-even win rate',u+'4']])+'<div class="note" id="'+u+'n"></div></div>';
  function c(){var w=g(el,u+'w')/100,aw=g(el,u+'aw'),al=g(el,u+'al'),co=g(el,u+'c');var e=w*aw-(1-w)*al-co;
    setT(el,u+'1',money(e),e>=0?'gain':'loss');setT(el,u+'2',num(e/al,2)+'R',e>=0?'gain':'loss');var pf=(w*aw)/((1-w)*al+co);setT(el,u+'3',num(pf,2));setT(el,u+'4',num(100*(al+co)/(aw+al),1)+'%');
    $('#'+u+'n',el).textContent=e>=0?'Positive after costs. Treat that as a hypothesis until real trades confirm it.':'Negative after costs. Repeating this many times loses money, whatever the win rate.'}
  $$('input',el).forEach(function(i){i.oninput=c});c();
};
W.drawdown=function(el){
  var u='d'+(++uid);
  el.innerHTML='<div class="tool"><h4>Drawdown recovery</h4><div class="sub">The gain needed to get back to even after a loss is loss / (1 - loss).</div><label class="f">Account loss: <span id="'+u+'v">20</span>%<input type="range" id="'+u+'s" min="1" max="90" value="20"></label><div class="out" style="margin-top:12px"><div>Gain required<b id="'+u+'1">-</b></div><div>Account after loss (start $10,000)<b id="'+u+'2">-</b></div></div></div>';
  function c(){var l=parseFloat($('#'+u+'s',el).value);$('#'+u+'v',el).textContent=l;setT(el,u+'1','+'+num(100*l/(100-l),1)+'%');setT(el,u+'2',money(10000*(1-l/100),0))}
  $('#'+u+'s',el).oninput=c;c();
};
W.reality=function(el){
  var u='r'+(++uid);
  el.innerHTML='<div class="tool"><h4>Income reality check</h4><div class="sub">How much capital does a monthly income need at different sustained monthly returns? Most professional funds would be thrilled with 1% a month.</div><div class="fields">'+fld(u+'i','Target income per month ($)',5000,100)+'</div><div class="tw"><table><thead><tr><th>Monthly return</th><th class="num">Yearly equivalent</th><th class="num">Capital needed</th><th>Realism</th></tr></thead><tbody id="'+u+'b"></tbody></table></div><div class="note">Returns compound, so the yearly figure is (1 + monthly)^12 - 1. Taxes and costs come out of these numbers.</div></div>';
  var rows=[[1,'Excellent for a professional'],[2,'Elite, rarely sustained'],[5,'Extraordinary; almost no one holds this'],[10,'Not a plan; a lottery ticket']];
  function c(){var I=g(el,u+'i');$('#'+u+'b',el).innerHTML=rows.map(function(r){var y=(Math.pow(1+r[0]/100,12)-1)*100;return '<tr><td>'+r[0]+'%</td><td class="num">+'+num(y,0)+'%</td><td class="num">'+money(I/(r[0]/100),0)+'</td><td>'+r[1]+'</td></tr>'}).join('')}
  $('#'+u+'i',el).oninput=c;c();
};
W.costs=function(el){
  var u='c'+(++uid);
  el.innerHTML='<div class="tool"><h4>Cost hurdle</h4><div class="sub">How much your account must earn every month just to pay spreads, slippage and fees.</div><div class="fields">'+fld(u+'a','Account ($)',10000,100)+fld(u+'sh','Shares per trade',200,10)+fld(u+'sl','Slippage + fees per share, per side ($)',0.01,0.005)+fld(u+'t','Trades per day',6,1)+fld(u+'d','Trading days per month',21,1)+'</div>'+outs([['Cost per round trip',u+'1'],['Cost per month',u+'2'],['Monthly return needed to break even',u+'3']])+'</div>';
  function c(){var A=g(el,u+'a'),sh=g(el,u+'sh'),sl=g(el,u+'sl'),t=g(el,u+'t'),d=g(el,u+'d');var rt=sh*sl*2,m=rt*t*d;setT(el,u+'1',money(rt));setT(el,u+'2',money(m,0));setT(el,u+'3',num(100*m/A,1)+'%')}
  $$('input',el).forEach(function(i){i.oninput=c});c();
};
var CON={ES:['E-mini S&P 500',50,0.25],MES:['Micro E-mini S&P 500',5,0.25],NQ:['E-mini Nasdaq-100',20,0.25],MNQ:['Micro E-mini Nasdaq-100',2,0.25],CL:['Crude oil (1,000 bbl)',1000,0.01],GC:['Gold (100 oz)',100,0.1]};
W.fut=function(el){
  var u='f'+(++uid);
  el.innerHTML='<div class="tool"><h4>Futures tick and risk calculator</h4><div class="sub">Dollar value of a move = points x point value. Contract specifications are set by the exchange; verify them before trading.</div><div class="fields"><label class="f">Contract<select id="'+u+'c">'+Object.keys(CON).map(function(k){return '<option value="'+k+'">'+k+' - '+CON[k][0]+'</option>'}).join('')+'</select></label>'+fld(u+'a','Account ($)',10000,100)+fld(u+'r','Risk per trade (%)',1,0.1)+fld(u+'p','Stop distance (points)',4,0.25)+'</div>'+outs([['Point value',u+'1'],['Tick size / value',u+'2'],['Risk per contract',u+'3'],['Contracts allowed',u+'4']])+'<div class="note" id="'+u+'n"></div></div>';
  function c(){var k=$('#'+u+'c',el).value,C=CON[k],A=g(el,u+'a'),R=g(el,u+'r'),P=g(el,u+'p');var rc=P*C[1],n=rc>0?Math.floor(A*R/100/rc):0;
    setT(el,u+'1',money(C[1],0));setT(el,u+'2',C[2]+' pt = '+money(C[1]*C[2]));setT(el,u+'3',money(rc));setT(el,u+'4',num(n,0));
    $('#'+u+'n',el).textContent=n===0?'One contract already risks more than your limit. Choose a smaller contract or a tighter stop, or skip the trade.':'Total risk: '+money(n*rc)+'. Futures margin is set separately by your broker and the exchange.'}
  $$('input,select',el).forEach(function(i){i.oninput=c;i.onchange=c});c();
};
W.payoff=function(el){
  var u='o'+(++uid);
  el.innerHTML='<div class="tool"><h4>Option payoff at expiration (one contract = 100 shares)</h4><div class="sub">A long option can lose its whole premium. The chart shows profit or loss per contract at expiration.</div><div class="fields"><label class="f">Type<select id="'+u+'t"><option value="call">Long call</option><option value="put">Long put</option></select></label>'+fld(u+'k','Strike',52,0.5)+fld(u+'p','Premium per share',1.2,0.05)+fld(u+'s','Stock price at expiration',56,0.5)+'</div><svg id="'+u+'g" viewBox="0 0 600 240" role="img" aria-label="Option payoff diagram"></svg>'+outs([['Cost (max loss for buyer)',u+'1'],['Break-even price',u+'2'],['Profit or loss at that price',u+'3']])+'</div>';
  function pl(t,K,P,S){return (t==='call'?Math.max(S-K,0):Math.max(K-S,0))*100-P*100}
  function c(){var t=$('#'+u+'t',el).value,K=g(el,u+'k'),P=g(el,u+'p'),S=g(el,u+'s');var lo=K*0.8,hi=K*1.2,pts=[],mn=1e9,mx=-1e9;for(var i=0;i<=60;i++){var x=lo+(hi-lo)*i/60,y=pl(t,K,P,x);pts.push([x,y]);mn=Math.min(mn,y);mx=Math.max(mx,y)}
    var pad=(mx-mn)*.12||10;mn-=pad;mx+=pad;var X=function(x){return 40+(x-lo)/(hi-lo)*540},Y=function(y){return 16+(mx-y)/(mx-mn)*190};
    var d=pts.map(function(p,i){return (i?'L':'M')+X(p[0]).toFixed(1)+' '+Y(p[1]).toFixed(1)}).join(' ');
    var zy=Y(0),ty=Y(pl(t,K,P,S));
    $('#'+u+'g',el).innerHTML='<line x1="40" x2="580" y1="'+zy+'" y2="'+zy+'" stroke="var(--line)" stroke-width="1"/><path d="'+d+'" fill="none" stroke="var(--accent)" stroke-width="3"/><line x1="'+X(K)+'" x2="'+X(K)+'" y1="16" y2="206" stroke="var(--muted)" stroke-dasharray="4 4" stroke-width="1"/><text x="'+X(K)+'" y="228" text-anchor="middle" font-size="12" fill="var(--muted)" font-family="IBM Plex Mono,monospace">strike '+K+'</text><circle cx="'+X(Math.min(Math.max(S,lo),hi))+'" cy="'+ty+'" r="6" fill="var(--accent)"/><text x="44" y="'+(zy-6)+'" font-size="12" fill="var(--muted)" font-family="IBM Plex Mono,monospace">$0</text><text x="'+(X(S)>430?X(S)-10:X(S)+10)+'" y="'+(ty-10)+'" text-anchor="'+(X(S)>430?'end':'start')+'" font-size="13" fill="var(--ink)" font-family="IBM Plex Mono,monospace">'+money(pl(t,K,P,S),0)+'</text>';
    setT(el,u+'1',money(P*100,0));setT(el,u+'2',money(t==='call'?K+P:K-P));setT(el,u+'3',money(pl(t,K,P,S),0),pl(t,K,P,S)>=0?'gain':'loss')}
  $$('input,select',el).forEach(function(i){i.oninput=c;i.onchange=c});c();
};
W.sim=function(el){
  var u='s'+(++uid);
  el.innerHTML='<div class="tool"><h4>Equity curve simulator</h4><div class="sub">Same strategy, random luck. Each line is one possible future. Change the risk per trade and watch what survives the bad streaks.</div><div class="fields">'+fld(u+'w','Win rate (%)',40,1)+fld(u+'rr','Average reward : risk',2,0.1)+fld(u+'r','Risk per trade (% of account)',1,0.25)+fld(u+'c','Cost per trade (R)',0.05,0.01)+fld(u+'n','Trades',300,10)+'</div><canvas id="'+u+'cv" aria-label="Simulated equity curves"></canvas>'+outs([['Expectancy per trade',u+'1'],['Runs ending below start',u+'2'],['Runs that fell 50% or more',u+'3'],['Median ending value (start 100)',u+'4']])+'<div class="row" style="margin-top:10px"><button class="btn sm" id="'+u+'b">Run again</button></div></div>';
  function c(){var p=g(el,u+'w')/100,rr=g(el,u+'rr'),r=g(el,u+'r')/100,co=g(el,u+'c'),n=Math.min(Math.max(Math.round(g(el,u+'n')),10),2000);
    var runs=60,curves=[],below=0,half=0,fin=[];
    for(var i=0;i<runs;i++){var e=100,pk=100,c2=[e],hit=false;for(var t=0;t<n;t++){var win=Math.random()<p;e=e*(1+r*(win?rr:-1)-r*co);if(e<0.01)e=0.01;if(e>pk)pk=e;if(e<=pk*0.5)hit=true;c2.push(e)}curves.push(c2);if(e<100)below++;if(hit)half++;fin.push(e)}
    fin.sort(function(a,b){return a-b});var ex=p*rr-(1-p)-co;
    setT(el,u+'1',num(ex,3)+'R',ex>=0?'gain':'loss');setT(el,u+'2',Math.round(100*below/runs)+'%');setT(el,u+'3',Math.round(100*half/runs)+'%');setT(el,u+'4',num(fin[Math.floor(runs/2)],0));
    var cv=$('#'+u+'cv',el),dpr=window.devicePixelRatio||1,W2=cv.clientWidth,H2=cv.clientHeight;cv.width=W2*dpr;cv.height=H2*dpr;var x=cv.getContext('2d');x.scale(dpr,dpr);x.clearRect(0,0,W2,H2);
    var st=getComputedStyle(document.documentElement),col=st.getPropertyValue('--accent').trim()||'#0a6c8c',mut=st.getPropertyValue('--muted').trim()||'#55637a',ln=st.getPropertyValue('--line').trim()||'#ddd';
    var mn=Math.log(1),mx=Math.log(Math.max.apply(null,fin.concat([200]))*1.3);var lmin=Math.log(Math.max(Math.min.apply(null,curves.map(function(cc){return Math.min.apply(null,cc)})),1)*0.9);mn=Math.min(lmin,Math.log(50));
    function X(i){return 34+i/n*(W2-44)}function Y(v){return H2-18-(Math.log(Math.max(v,0.01))-mn)/(mx-mn)*(H2-30)}
    x.strokeStyle=ln;x.lineWidth=1;x.font='11px monospace';x.fillStyle=mut;[50,100,200,500,1000].forEach(function(v){if(Math.log(v)>mn&&Math.log(v)<mx){x.beginPath();x.moveTo(34,Y(v));x.lineTo(W2-8,Y(v));x.stroke();x.fillText(v,2,Y(v)+4)}});
    x.strokeStyle=mut;x.setLineDash([5,4]);x.beginPath();x.moveTo(34,Y(100));x.lineTo(W2-8,Y(100));x.stroke();x.setLineDash([]);
    curves.forEach(function(cc,k){x.strokeStyle=col;x.globalAlpha=.35;x.lineWidth=1.2;x.beginPath();var step=Math.max(1,Math.floor(n/300));for(var i=0;i<=n;i+=step){var px=X(i),py=Y(cc[i]);if(i===0)x.moveTo(px,py);else x.lineTo(px,py)}x.stroke()});x.globalAlpha=1;
    x.fillStyle=mut;x.fillText('trades',W2-46,H2-4);
  }
  $$('input',el).forEach(function(i){i.oninput=c});$('#'+u+'b',el).onclick=c;
  setTimeout(c,30);
};
